            `\u0412\u043E\u043F\u0440\u043E\u0441 \u043E \xAB${f.basename}\xBB`,
            "\u0427\u0442\u043E \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u0441 \u044D\u0442\u043E\u0439 \u0437\u0430\u043C\u0435\u0442\u043A\u043E\u0439?",
            (q) => this.ask(`\u041F\u0440\u043E \u0437\u0430\u043C\u0435\u0442\u043A\u0443 [[${f.basename}]] (${f.path}): ${q}`)
